import {lazy,Suspense,useEffect,useRef,useState,type ReactNode} from 'react';
import {ArrowDownToLine,ArrowLeft,ArrowRight,ArrowUpRight,Box,Check,CheckCheck,ChevronDown,ChevronRight,Columns3,Copy,Download,Eye,EyeOff,FileBox,FileText,FileCheck2,Folder,GitBranch,Grip,History,Home,Info,Layers,LayoutGrid,Lock,Map,Menu,MessageSquare,MoreHorizontal,PanelLeftClose,Play,Plus,Redo2,RefreshCw,Ruler,Search,Settings2,ShieldCheck,SlidersHorizontal,Sparkles,Square,SquareDashed,Table2,Trash2,Undo2,Unlock,Upload,Warehouse,X,Zap,Droplets,Armchair,AlertTriangle,CheckCircle2,Loader2,Send,Grid2X2,Globe,ExternalLink,Link2,Sun,Flame} from 'lucide-react';
import type {Building,Check as CheckType,Column,Diff,Layers as LayerState,Layer,Project,Quantity,Revision,Room,Tab,Brief,Rate} from './types';
