 {modal==='generate'&&<Modal title="Explore layout alternatives" onClose={()=>setModal('')} wide><div className="modal-body"><p className="modal-intro">Keep the structural grid and circulation fixed. Solve room dimensions and positions against your brief, then compare the impact.</p><div className="generation-facts"><span><Lock size={14}/>{b.rooms.filter(r=>r.locked).length} locked room</span><span><Columns3 size={14}/>{b.columns.filter(c=>c.active).length} fixed supports</span><span><Ruler size={14}/>{b.width} × {b.depth} m envelope</span></div><div className="generation-actions"><button className="button secondary" onClick={()=>setModal('brief')}><SlidersHorizontal size={14}/> Edit brief</button><button className="button primary" disabled={!!busy} onClick={generate}>{busy?<Loader2 size={14} className="spin"/>:<Sparkles size={14}/>} Generate candidates</button></div>{layoutInfo&&<p className="scope-note small">{layoutInfo}</p>}<div className="variant-list">{variants.map((v,i)=><button key={v.revision.id} className="variant" onClick={()=>{setPreview(v.revision);setTab('design');setModal('')}}><div className="variant-mini"><svg viewBox="-0.2 -0.2 12.4 9.4">{v.revision.model.rooms.map((room:Room)=><rect key={room.id} x={room.x} y={room.y} width={room.w} height={room.h} fill={room.kind==='bathroom'?'#d3dfd0':room.kind==='kitchen'?'#e2dcc1':'#edece4'} stroke="#7d8b7b" strokeWidth=".05"/>)}</svg></div><div><strong>{v.label}</strong><p>{money(v.revision.results.quantities.total)} <span>· {v.revision.results.summary.fail} findings</span></p><small>{v.solver_status.toLowerCase()} · {num(v.elapsed_ms,0)} ms · seed 42</small><small>{v.objective_description}</small></div><ArrowUpRight size={18}/></button>)}</div>{!variants.length&&!layoutInfo&&<div className="generation-empty"><LayoutGrid size={30}/><p>Alternatives appear here with calculated checks and quantities.</p></div>}</div></Modal>}
