 {modal==='element'&&<Modal title="Place an element" onClose={()=>setModal('')}><ElementForm model={b} selected={selected} busy={!!busy} onSubmit={async cmd=>{await propose([cmd],'Place '+String(cmd.name));setModal('');setSelected(String(cmd.id));setLayers({...layers,electrical:true,plumbing:true,furniture:true})}}/></Modal>}
 {modal==='grid'&&<Modal title="Structural grid" onClose={()=>setModal('')}><GridForm model={b} busy={!!busy} onSubmit={async (x,y)=>{await propose([{type:'set_grid',x,y}],'Reconfigured structural grid');setModal('')}}/></Modal>}
