 {modal==='import'&&<Modal title="Import project data" onClose={()=>setModal('')}><ImportForm busy={!!busy} onImport={(kind,text,units)=>run('Validating imported data',async()=>{let next:Revision;if(kind==='project'){const parsed=JSON.parse(text);next=await api('/import/project',{model:parsed.model||parsed})}else if(kind==='boundary'){const parsed=JSON.parse(text);next=await api('/commands',{base_revision:active.id,command_id:crypto.randomUUID(),label:'Imported boundary',commands:[{type:'set_site',site:{...b.site,boundary:parsed.boundary||parsed}}]})}else next=await api('/import/survey',{base_revision:active.id,csv_text:text,units});setPreview(next);await refresh();setModal('');setTab(kind==='project'?'workflow':'site')})}/></Modal>}
